-- Template #1: 2 Hours After Breakfast Blood Sugar (2 hrs ABF) (Category ID: 100003)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('2 Hours After Breakfast Blood Sugar (2 hrs ABF)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Blood Glucose (2 hrs ABF)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 7.8 mmol/L (Normal)<br>7.8 - 11.0 mmol/L (Impaired Glucose Tolerance)<br>&ge; 11.1 mmol/L (Diabetes Mellitus)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Corresponding Value in mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 140 mg/dL (Normal)<br>140 - 199 mg/dL (IGT)<br>&ge; 200 mg/dL (Diabetes Mellitus)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Urine Sugar</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Fluoride Plasma collected 2 hours after completion of standard meal. Method: GOD-POD Enzymatic.</div>\n</div>', '100003', '98', '1');

-- Template #2: Fasting Blood Sugar (FBS) (Category ID: 100002)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Fasting Blood Sugar (FBS)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Fasting Plasma Glucose (FBS)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">3.9 - 6.1 mmol/L (Normal)<br>6.1 - 6.9 mmol/L (Impaired Fasting Glucose)<br>&ge; 7.0 mmol/L (Diabetes Mellitus)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Corresponding Value in mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">70 - 110 mg/dL (Normal)<br>110 - 125 mg/dL (IFG)<br>&ge; 126 mg/dL (Diabetes Mellitus)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Urine Sugar</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Fluoride Plasma collected after 8-10 hours overnight fasting. Method: GOD-POD Enzymatic.</div>\n</div>', '100002', '98', '1');

