INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Thyroxine (T4)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Thyroxine (T4)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ug/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: 4.5 - 12.0 ug/dL<br>Children (1-5 yrs): 7.3 - 15.0 ug/dL<br>Pregnancy: 1.5 times non-pregnant range</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Chemiluminescence Immunoassay (CLIA). Specimen: Serum.</div>\n</div>', '100000', '98', '1');

