VALUES ('Triiodothyronine (T3)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Triiodothyronine (T3)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: 0.80 - 2.00 ng/mL<br>Children: 1.00 - 2.60 ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Chemiluminescence Immunoassay (CLIA). Specimen: Serum.</div>\n</div>', '99999', '98', '1');

-- Template #6: Serum Thyroid-Stimulating Hormone (TSH) (Category ID: 99998)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Serum Thyroid-Stimulating Hormone (TSH)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum TSH (3rd Generation)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">uIU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults (non-pregnant): 0.27 - 4.20 uIU/mL<br>Pregnancy (1st trimester): 0.10 - 2.50 uIU/mL<br>Pregnancy (2nd trimester): 0.20 - 3.00 uIU/mL<br>Pregnancy (3rd trimester): 0.30 - 3.00 uIU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Electrochemiluminescence Immunoassay (ECLIA). Ultra-sensitive 3rd Generation TSH assay.</div>\n</div>', '99998', '98', '1');

-- Template #7: Luteinizing Hormone (LH) (Category ID: 99997)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Luteinizing Hormone (LH)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Luteinizing Hormone (LH)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mIU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Males: 1.7 - 8.6 mIU/mL<br>Adult Females:<br>&bull; Follicular Phase: 2.4 - 12.6 mIU/mL<br>&bull; Mid-cycle Peak: 14.0 - 95.6 mIU/mL<br>&bull; Luteal Phase: 1.0 - 11.4 mIU/mL<br>&bull; Post-menopausal: 7.7 - 58.5 mIU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Chemiluminescence Immunoassay (CLIA). Specimen: Serum.</div>\n</div>', '99997', '98', '1');

