-- Template #9: Free Thyroxine (FT4) (Category ID: 99995)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Free Thyroxine (FT4)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Free Thyroxine (FT4)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ng/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: 0.93 - 1.70 ng/dL (12.0 - 22.0 pmol/L)<br>Pregnancy (1st trimester): 0.94 - 1.52 ng/dL<br>Pregnancy (2nd trimester): 0.75 - 1.32 ng/dL<br>Pregnancy (3rd trimester): 0.65 - 1.21 ng/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Electrochemiluminescence Immunoassay (ECLIA). Specimen: Serum.</div>\n</div>', '99995', '98', '1');

-- Template #10: ESR (Category ID: 99994)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('ESR', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Erythrocyte Sedimentation Rate (ESR)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mm / 1st hr</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Male: 0 - 10 mm in 1st hour<br>Female: 0 - 20 mm in 1st hour<br>Elderly (&gt; 50 yrs): Male: 0 - 15, Female: 0 - 25 mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Westergren Method. Specimen: Sodium Citrate / EDTA Whole Blood.</div>\n</div>', '99994', '98', '1');

-- Template #11: Febrile Antigen (Category ID: 179)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Febrile Antigen', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Antigen</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Titre</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval / Cutoff</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Interpretation</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Salmonella typhi \'O\'</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Titre &lt; 1:80 (Normal)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Salmonella typhi \'H\'</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Titre &lt; 1:80 (Normal)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Salmonella paratyphi \'AH\'</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Titre &lt; 1:80 (Normal)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Salmonella paratyphi \'BH\'</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Titre &lt; 1:80 (Normal)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Brucella abortus</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Titre &lt; 1:80 (Negative)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Proteus OX19</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Titre &lt; 1:80 (Negative)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Slide & Tube Agglutination Test. Significant titre is &ge; 1:160 in endemic areas.</div>\n</div>', '179', '98', '1');

-- Template #12: Hb Electrophoresis (Category ID: 178)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Hb Electrophoresis', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Hemoglobin Variant</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Hemoglobin A (Hb A)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">%</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">95.0 - 98.0 %</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Hemoglobin A2 (Hb A2)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">%</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">1.5 - 3.5 % (&gt; 3.5% indicates Beta Thalassemia Trait)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Hemoglobin F (Hb F)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">%</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 1.0 % (Adults)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Hemoglobin S (Hb S)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">%</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Hemoglobin E (Hb E)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">%</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Nil</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Opinion / Impression</div>\n<div style=\"padding:8px; border:1px solid #d0d7de; background:#fff; min-height:50px;\">\nNormal adult hemoglobin electrophoresis pattern. No abnormal hemoglobin variant detected.\n</div>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Automated Capillary Electrophoresis / High-Performance Liquid Chromatography (HPLC).</div>\n</div>', '178', '98', '1');

-- Template #13: S. Lipase (Category ID: 177)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S. Lipase', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Lipase</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">13 - 60 U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Enzymatic Colorimetric. Specimen: Serum. Elevated values (&gt; 3x upper limit) are highly sensitive and specific for acute pancreatitis.</div>\n</div>', '177', '98', '1');

-- Template #14: ANA (Category ID: 176)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('ANA', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Titre</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Pattern / Remarks</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Value</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Antinuclear Antibodies (ANA)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&lt; 1:40</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">No fluorescent pattern seen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Negative: &lt; 1:40<br>Borderline: 1:40 - 1:80<br>Positive: &ge; 1:80</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Clinical Interpretation</div>\n<div style=\"padding:8px; border:1px solid #d0d7de; background:#fff; min-height:45px;\">\nNegative for Antinuclear Antibodies. Does not support a diagnosis of Systemic Lupus Erythematosus (SLE) or related systemic autoimmune diseases.\n</div>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Indirect Immunofluorescence Assay (IFA) on HEp-2 cells / ELISA. Specimen: Serum.</div>\n</div>', '176', '98', '1');

-- Template #15: Blood for C/S (Category ID: 175)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Blood for C/S', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Examination</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Observation / Findings</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Specimen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Venous Blood in BHI Broth Bottle</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Incubation Period</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Incubated at 37&deg;C for 24, 48, 72 hours and up to 7 days</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Culture Result</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">No bacterial growth observed after 72 hours of aerobic incubation at 37&deg;C.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Organism Isolated</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">None</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Antibiotic Susceptibility Test (AST)</div>\n<p style=\"font-size:12px; color:#666;\"><em>(Antibiotic sensitivity table will be reported if pathogenic organism is isolated)</em></p>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Antibiotic Name</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Zone Diameter (mm)</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Susceptibility</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\" colspan=\"3\" style=\"text-align:center; color:#888; font-style:italic;\">No organism isolated; AST not applicable.</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Automated Blood Culture System / Conventional Subculture on Blood Agar & MacConkey Agar. Final report issued after 7 days if negative.</div>\n</div>', '175', '98', '1');

-- Template #16: Iron Profile (Category ID: 174)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Iron Profile', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Iron</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ug/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Male: 65 - 175 ug/dL<br>Female: 50 - 170 ug/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Iron Binding Capacity (TIBC)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ug/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">250 - 450 ug/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Transferrin Saturation</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">%</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">20 - 50 %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Ferritin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Male: 30 - 400 ng/mL<br>Adult Female: 15 - 150 ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Fasting Morning Serum (Iron has marked diurnal variation). Method: Ferrozine / CLIA.</div>\n</div>', '174', '98', '1');

-- Template #17: Vitamin D-Level (Category ID: 173)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Vitamin D-Level', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interpretation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">25-Hydroxy Vitamin D [25(OH)D]</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 20 ng/mL: Deficiency<br>20 - 29 ng/mL: Insufficiency<br>30 - 100 ng/mL: Sufficiency / Optimal<br>&gt; 100 ng/mL: Possible Toxicity</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Electrochemiluminescence Immunoassay (ECLIA). Specimen: Serum. Reference source: Endocrine Society Clinical Guidelines.</div>\n</div>', '173', '98', '1');

-- Template #18: Semen Analysis (Category ID: 172)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Semen Analysis', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">1. Physical & Macroscopic Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">WHO 6th Edition (2021) Reference</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Period of Abstinence</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">3 Days</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">2 - 7 Days</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Time of Collection & Examination</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Examined within 60 mins of collection</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Color / Appearance</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Greyish White / Opalescent</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Greyish White / Opalescent</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Liquefaction Time</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">25 mins</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Complete within 60 mins at 37&deg;C</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Volume</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 1.4 mL</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Viscosity</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Normal</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Normal (&lt; 2 cm thread)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Reaction (pH)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">7.8</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 7.2</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">2. Microscopic & Quantitative Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">WHO Reference Limits</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Sperm Concentration</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong> Mill/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 16.0 Million/mL</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Sperm Count</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; Mill/Ejaculate</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 39.0 Million/ejaculate</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Total Motility (PR + NP)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 42 %</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&bull; Progressive Motility (PR)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 30 %</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&bull; Non-Progressive Motility (NP)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">-</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&bull; Immotile Spermatozoa</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">-</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Sperm Vitality (Viability)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 54 % (Eosin-Nigrosin)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Normal Sperm Morphology</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 4.0 % (Kruger strict criteria)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Pus Cells (Leukocytes)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; /HPF</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"&lt; 1.0 Million/mL (&lt; 5/HPF)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">RBCs</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil /HPF</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Epithelial Cells</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Few /HPF</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Few</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Sperm Agglutination</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Nil</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression / Opinion</div>\n<div style=\"padding:8px; border:1px solid #d0d7de; background:#fff; min-height:45px;\">\nNormozoospermia (Normal semen parameters according to WHO 6th edition criteria).\n</div>\n</div>', '172', '98', '1');

-- Template #19: HbA1c (Category ID: 171)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('HbA1c', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Glycated Hemoglobin (HbA1c)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">%</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 5.7 % : Non-Diabetic<br>5.7 - 6.4 % : Pre-diabetes (High risk)<br>&ge; 6.5 % : Diabetes Mellitus</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Estimated Average Glucose (eAG)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 117 mg/dL (Normal)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">eAG in mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 6.5 mmol/L (Normal)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: High Performance Liquid Chromatography (HPLC) / Ion Exchange. Certified by NGSP & standardized to IFCC reference method.</div>\n</div>', '171', '98', '1');

-- Template #20: Pus for C/S (Category ID: 170)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Pus for C/S', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Examination</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Findings</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Specimen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Pus / Wound Swab</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Gram Stain Microscopy</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Pus cells seen: Moderate; Organism: &nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Culture at 37&deg;C (48 hrs)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">No bacterial growth after 48 hours of aerobic incubation at 37&deg;C.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Organism Isolated</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">None</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Antibiotic Sensitivity Pattern (Kirby-Bauer Disk Diffusion)</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Antimicrobial Agent</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Zone (mm)</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Susceptibility (S / I / R)</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\" colspan=\"3\" style=\"text-align:center; color:#888; font-style:italic;\">No pathogenic growth isolated. AST not applicable.</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Guidelines: CLSI M100. Specimen cultured on Blood Agar & MacConkey Agar.</div>\n</div>', '170', '98', '1');

-- Template #21: Hbs AG Confirmatory (Category ID: 169)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Hbs AG Confirmatory', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Index Value (S/CO)</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Cutoff Criteria</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">HBsAg Confirmatory Assay</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NON-REACTIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Non-Reactive: &lt; 0.90 S/CO<br>Borderline: 0.90 - 1.00 S/CO<br>Reactive: &ge; 1.00 S/CO</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Electrochemiluminescence Immunoassay (ECLIA) / ELISA. Specimen: Serum. Confirmatory neutralization assay performed when indicated.</div>\n</div>', '169', '98', '1');

-- Template #22: Troponin I (Category ID: 168)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Troponin I', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Cutoff</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Cardiac Troponin I (cTnI)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 0.04 ng/mL : Negative / Normal<br>&ge; 0.04 ng/mL : Positive (Suggestive of Myocardial Injury)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Quantitative Fluorescence Immunoassay / CLIA. Clinical correlation with ECG and clinical symptoms is essential for Acute Coronary Syndrome.</div>\n</div>', '168', '98', '1');

-- Template #23: Testosteron (Category ID: 167)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Testosteron', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Serum Testosterone</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ng/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Male (20-49 yrs): 249 - 836 ng/dL<br>Adult Male (&ge; 50 yrs): 193 - 740 ng/dL<br>Adult Female: 8.4 - 48.1 ng/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Chemiluminescence Immunoassay (CLIA). Specimen: Morning Serum (testosterone peaks between 7 AM and 10 AM).</div>\n</div>', '167', '98', '1');

-- Template #24: Dengue NS-1/IGG/IGM (Category ID: 166)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Dengue NS-1/IGG/IGM', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Dengue Marker</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Method</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Clinical Significance</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Dengue NS1 Antigen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Immunochromatography</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Detected in acute phase (Day 1 - 7 of fever)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Dengue IgM Antibody</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Immunochromatography</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Appears after day 4-5; indicates primary infection</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Dengue IgG Antibody</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Immunochromatography</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Indicates secondary infection or past exposure</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Interpretation</div>\n<div style=\"padding:8px; border:1px solid #d0d7de; background:#fff; min-height:45px;\">\nNegative for Dengue NS1 Antigen and Dengue IgM/IgG Antibodies.\n</div>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> A negative result does not rule out Dengue infection if collected very early. Repeat testing or Platelet / Hematocrit monitoring recommended if clinical suspicion persists.</div>\n</div>', '166', '98', '1');

-- Template #25: S.Electrolyte (Category ID: 165)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S.Electrolyte', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Analyte</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Sodium (Na+)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">135 - 145 mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Potassium (K+)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">3.5 - 5.1 mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Chloride (Cl-)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">98 - 107 mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Bicarbonate (HCO3-)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">22 - 29 mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Anion Gap</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">8 - 16 mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Ion Selective Electrode (ISE) Direct Method. Specimen: Serum (Non-hemolyzed).</div>\n</div>', '165', '98', '1');

-- Template #26: S.Amylase (Category ID: 163)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S.Amylase', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Amylase</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">28 - 100 U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Enzymatic Colorimetric (CNPG3). Specimen: Serum.</div>\n</div>', '163', '98', '1');

-- Template #27: S.IGE (Level) (Category ID: 162)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S.IGE (Level)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Serum IgE</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">IU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: &lt; 100 IU/mL<br>Children (1-5 yrs): &lt; 60 IU/mL<br>Children (6-14 yrs): &lt; 90 IU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Chemiluminescence Immunoassay (CLIA). Specimen: Serum. Elevated in atopic allergy, bronchial asthma, and parasitic infections.</div>\n</div>', '162', '98', '1');

-- Template #28: Prothombin Time (Category ID: 161)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Prothombin Time', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Coagulation Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Patient PT</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Seconds</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">11.0 - 15.0 Seconds</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Control PT</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Seconds</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">12.0 Seconds</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Prothrombin Ratio (PR)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">0.9 - 1.2</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">INR (Intl. Normalized Ratio)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Normal: 0.8 - 1.2<br>Therapeutic Target for Oral Anticoagulation (Warfarin): 2.0 - 3.0</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Citrated Plasma (1:9 ratio). Method: Photo-optical Clot Detection.</div>\n</div>', '161', '98', '1');

-- Template #29: S.PROLACTIN (Category ID: 160)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S.PROLACTIN', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Prolactin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Males: 4.04 - 15.2 ng/mL<br>Non-pregnant Females: 4.79 - 23.3 ng/mL<br>Post-menopausal Females: 3.00 - 18.0 ng/mL<br>Pregnant Females: 34 - 386 ng/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Electrochemiluminescence Immunoassay (ECLIA). Specimen: Serum collected in morning at rest.</div>\n</div>', '160', '98', '1');

-- Template #30: Urine C/S (Category ID: 136)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Urine C/S', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Examination</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Findings</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Specimen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Clean-catch Midstream Urine (MSU)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Gram Stain Microscopy</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Pus cells: &nbsp; /HPF; Organisms: &nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Culture Result (37&deg;C, 24-48 hrs)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">No significant bacteriuria / bacterial growth after 48 hours of aerobic incubation.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Colony Count</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 10,000 CFU/mL (Not significant)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Organism Isolated</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">None</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Antibiotic Sensitivity Pattern (AST)</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Antibiotic</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Susceptibility</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Antibiotic</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Susceptibility</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\" colspan=\"4\" style=\"text-align:center; color:#888; font-style:italic;\">No significant growth isolated. Sensitivity testing not indicated.</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Significant bacteriuria is defined as &ge; 10^5 CFU/mL of a single uropathogen according to Kass criteria.</div>\n</div>', '136', '98', '1');

-- Template #31: Urine P/T (Category ID: 135)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Urine P/T', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Sensitivity / Cutoff</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Interpretation</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Urine Pregnancy Test (hCG)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">25 mIU/mL human Chorionic Gonadotropin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">No pregnancy-specific hCG detected</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Rapid Immunochromatographic Assay for beta-hCG. Specimen: Early Morning First Voided Urine.</div>\n</div>', '135', '98', '1');

-- Template #32: Urine R/E (Category ID: 134)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Urine R/E', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">1. Physical Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Color</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Straw / Pale Yellow</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Specific Gravity</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">1.015 (1.005 - 1.030)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Appearance</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Clear</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Sediment</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">2. Chemical Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Reaction (pH)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">6.0 (Acidic)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Ketones</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Albumin / Protein</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Bilirubin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Sugar / Glucose</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Urobilinogen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Normal</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Blood / Hemoglobin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Nitrite</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">3. Microscopic Examination (Centrifuged Deposit)</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Element</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Element</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Pus Cells</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">1 - 2 /HPF (0 - 5)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Casts</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">RBCs</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil /HPF (0 - 2)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Crystals</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Epithelial Cells</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Few /HPF</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Amorphous Deposits</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Yeast Cells</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Bacteria</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n</tbody>\n</table>\n</div>', '134', '98', '1');

-- Template #33: OBT (Category ID: 133)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('OBT', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Method</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Clinical Significance</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Occult Blood in Stool (OBT)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Immunochemical (FOBT)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Specific for human hemoglobin; no dietary restriction required</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Fresh fecal sample. A negative test does not completely exclude lower GI lesions as bleeding may be intermittent.</div>\n</div>', '133', '98', '1');

-- Template #34: Stool C/S (Category ID: 132)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Stool C/S', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Examination</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Findings</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Specimen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Fresh Stool</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Direct Microscopy</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Pus cells: Few; RBCs: Nil; Cysts/Ova: Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Culture Result (48 hrs)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Normal fecal enteric flora isolated. No growth of enteric pathogens (Salmonella, Shigella, Vibrio cholerae).</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Pathogen Isolated</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">None</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Antibiotic Sensitivity Test</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Antimicrobial Agent</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Zone (mm)</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Susceptibility</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\" colspan=\"3\" style=\"text-align:center; color:#888; font-style:italic;\">No enteric pathogen isolated. AST not applicable.</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen inoculated onto MacConkey, SS Agar & TCBS. Incubated at 37&deg;C.</div>\n</div>', '132', '98', '1');

-- Template #35: Stool R/E (Category ID: 131)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Stool R/E', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">1. Physical Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Color</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Yellowish Brown</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Mucus</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Absent</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Consistency</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Formed / Semi-formed</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Blood</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Absent</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">2. Chemical Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Reaction (pH)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Neutral / Slightly Acidic</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Reducing Substances</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Occult Blood</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">3. Microscopic Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Element</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Element</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Protozoa (Cysts / Trophozoites)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Not Seen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Pus Cells</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">0 - 2 /HPF</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Helminths (Ova / Larvae)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Not Seen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Red Blood Cells (RBCs)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">E. histolytica / Giardia</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Not Seen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Macrophages</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Ascaris / Hookworm Ova</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Not Seen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Vegetable / Starch Granules</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Present (Few)</td></tr>\n</tbody>\n</table>\n</div>', '131', '98', '1');

-- Template #36: Alkaline phosphatase (Category ID: 130)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Alkaline phosphatase', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Alkaline Phosphatase (ALP)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: 44 - 147 U/L<br>Children (&lt; 15 yrs): Up to 350 U/L (Growing bones)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: p-Nitrophenylphosphate (pNPP) Kinetic Method (IFCC). Specimen: Serum.</div>\n</div>', '130', '98', '1');

-- Template #37: LFT (Category ID: 129)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('LFT', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Liver Function Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Bilirubin (Total)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">0.2 - 1.2 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Serum Bilirubin (Direct / Conjugated)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">0.0 - 0.3 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Serum Bilirubin (Indirect / Unconjugated)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">0.2 - 0.8 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">SGPT / ALT</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Male: &lt; 45 U/L; Female: &lt; 34 U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">SGOT / AST</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Male: &lt; 40 U/L; Female: &lt; 32 U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Alkaline Phosphatase (ALP)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: 44 - 147 U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Total Protein</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">6.4 - 8.3 g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Serum Albumin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">3.5 - 5.2 g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Serum Globulin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">2.3 - 3.5 g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">A / G Ratio</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">1.2 - 2.2</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Serum. Method: Fully Automated Clinical Chemistry Analyzer.</div>\n</div>', '129', '98', '1');

-- Template #38: PBF (Category ID: 128)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('PBF', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Peripheral Blood Film (PBF) Examination</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\" style=\"width:25%;\">Series</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Morphological Findings</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">RBC Series (Erythrocytes)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Predominantly normocytic and normochromic. Normal central pallor. No marked anisopoikilocytosis, polychromasia, or nucleated RBCs seen.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">WBC Series (Leukocytes)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Total count appears normal. Mature neutrophils and lymphocytes predominate in normal proportion. No toxic granulation or atypical/blast cells seen.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Platelets (Thrombocytes)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adequate in number on smear. Morphologically normal; normal granules and clumping noted.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Hemoparasites</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">No malarial parasite or microfilaria seen in the examined film.</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression & Clinical Advice</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#fff; min-height:50px;\">\n<strong>Impression:</strong> Normocytic Normochromic Blood Picture.<br>\n<small class=\"text-muted\">Correlate with Complete Blood Count (CBC) and clinical profile.</small>\n</div>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Stain: Leishman / Giemsa Stain. Examined under 100x Oil Immersion lens.</div>\n</div>', '128', '98', '1');

-- Template #39: Hb% (Category ID: 127)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Hb%', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Hemoglobin (Hb%)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Males: 13.5 - 17.5 g/dL<br>Adult Females: 12.0 - 15.5 g/dL<br>Children: 11.0 - 14.5 g/dL<br>Pregnant Females: &ge; 11.0 g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Cyanmethemoglobin Spectrophotometric Method / Automated Cell Counter. Specimen: EDTA Blood.</div>\n</div>', '127', '98', '1');

-- Template #40: S. Albumin (Category ID: 126)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S. Albumin', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Albumin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">3.5 - 5.2 g/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Bromocresol Green (BCG) Dye Binding Method. Specimen: Serum.</div>\n</div>', '126', '98', '1');

-- Template #41: Sputum for AFB (Category ID: 125)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Sputum for AFB', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Specimen</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Staining Method</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Microscopic Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Grading (WHO/RNTCP)</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Sample 1 (Spot)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Ziehl-Neelsen (ZN)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\"><strong>No Acid-Fast Bacilli Seen</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Sample 2 (Early Morning)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Ziehl-Neelsen (ZN)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\"><strong>No Acid-Fast Bacilli Seen</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Negative</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Grading Scale (WHO / RNTCP Criteria)</div>\n<div style=\"font-size:12px; color:#555; line-height:1.6; padding:8px; border:1px solid #e1e4e8; background:#fafbfc;\">\n&bull; <strong>Negative:</strong> Zero AFB per 100 oil immersion fields.<br>\n&bull; <strong>Scanty:</strong> 1-9 AFB per 100 fields (record exact number).<br>\n&bull; <strong>1+:</strong> 10-99 AFB per 100 fields.<br>\n&bull; <strong>2+:</strong> 1-10 AFB per field in at least 50 fields.<br>\n&bull; <strong>3+:</strong> &gt; 10 AFB per field in at least 20 fields.\n</div>\n</div>', '125', '98', '1');

-- Template #42: Tuberculin Test (MT) (Category ID: 124)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Tuberculin Test (MT)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Details</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Antigen Injected</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Purified Protein Derivative (PPD-RT 23) 2 TU / 5 TU (0.1 mL Intradermally)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Site of Injection</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Volar surface of Left Forearm</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Date & Time of Injection</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Date & Time of Reading</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&nbsp; (Read after 48 - 72 Hours)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Induration Diameter</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\"><strong>&nbsp; mm</strong> (Measured transverse diameter of induration, not erythema)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Interpretation</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\"><strong>NEGATIVE</strong> (&lt; 5 mm)</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Interpretation Criteria</div>\n<div style=\"font-size:12px; color:#555; padding:8px; border:1px solid #e1e4e8; background:#fafbfc;\">\n&bull; <strong>&ge; 5 mm:</strong> Positive in HIV-infected persons, recent contacts of active TB cases, or immunosuppressed patients.<br>\n&bull; <strong>&ge; 10 mm:</strong> Positive in high-prevalence areas (e.g. Bangladesh), high-risk clinical conditions.<br>\n&bull; <strong>&ge; 15 mm:</strong> Positive in persons with no known risk factors for TB.\n</div>\n</div>', '124', '98', '1');

-- Template #43: CRP (Category ID: 123)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('CRP', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">C-Reactive Protein (CRP)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 6.0 mg/L : Normal / Negative<br>&ge; 6.0 mg/L : Positive (Acute phase reactant / Inflammation)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Quantitative Immunoturbidimetric Assay. Specimen: Serum.</div>\n</div>', '123', '98', '1');

-- Template #44: Blood Grouping (Category ID: 122)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Blood Grouping', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Examination</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Anti-A</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Anti-B</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Anti-D (Rh)</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Final Blood Group</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Forward & Reverse Grouping</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\" style=\"font-size:16px; color:#c00;\"><strong>&nbsp;</strong></td></tr>\n</tbody>\n</table>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\" style=\"width:30%;\">ABO Blood Group</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\" style=\"font-size:15px; color:#1a3a60;\"><strong>&nbsp;</strong></td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Rh (D) Factor</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\" style=\"font-size:15px; color:#1a3a60;\"><strong>&nbsp;</strong></td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Slide & Tube Hemagglutination Technique using monoclonal Anti-A, Anti-B, and Anti-D sera.</div>\n</div>', '122', '98', '1');

-- Template #45: TPHA (Category ID: 121)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('TPHA', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Titre</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Value</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Treponema Pallidum Hemagglutination (TPHA)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NON-REACTIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&lt; 1:80</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Non-Reactive: &lt; 1:80<br>Reactive: &ge; 1:80</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Indirect Hemagglutination Assay for Treponema pallidum antibodies. Confirmatory treponemal test for Syphilis.</div>\n</div>', '121', '98', '1');

-- Template #46: VDRL (Category ID: 120)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('VDRL', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Titre (if Reactive)</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Value</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">VDRL / RPR Flocculation Test</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NON-REACTIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Non-Reactive</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Non-treponemal Carbon Antigen Flocculation (RPR / VDRL). Specimen: Serum. Biological false positives may occur in autoimmune diseases, leprosy, malaria, or pregnancy.</div>\n</div>', '120', '98', '1');

-- Template #47: ASO Titre (Category ID: 119)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('ASO Titre', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Anti-Streptolysin O (ASO) Titre</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">IU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: &lt; 200 IU/mL<br>Children (&le; 12 yrs): &lt; 300 IU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Quantitative Immunoturbidimetric / Latex Agglutination Method. Elevated titres indicate recent Group A Streptococcus infection (Rheumatic Fever, Glomerulonephritis).</div>\n</div>', '119', '98', '1');

-- Template #48: Widal Test (Category ID: 118)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Widal Test', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Salmonella Antigen</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">1:20</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">1:40</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">1:80</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">1:160</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">1:320</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Final Titre</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Salmonella typhi \'O\' (S. typhi O)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">+</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">+</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\">1:40</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Salmonella typhi \'H\' (S. typhi H)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">+</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">+</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\">1:40</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Salmonella paratyphi \'AH\'</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\">&lt; 1:20</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Salmonella paratyphi \'BH\'</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\">&lt; 1:20</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Clinical Interpretation</div>\n<div style=\"padding:8px; border:1px solid #d0d7de; background:#fff; min-height:45px;\">\nTitre &lt; 1:80 for S. typhi O and H antigens is not significant. No serological evidence of active Enteric (Typhoid) Fever at present.\n</div>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Tube Agglutination Technique. In endemic regions, a single titre of &ge; 1:160 for O and/or H antigen, or a four-fold rise in paired sera, is clinically significant.</div>\n</div>', '118', '98', '1');

-- Template #49: R/A Factor (Category ID: 117)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('R/A Factor', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Rheumatoid Factor (RA / RF)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">IU/mL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 14.0 IU/mL : Negative<br>&ge; 14.0 IU/mL : Positive</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Quantitative Immunoturbidimetric Assay. Specimen: Serum.</div>\n</div>', '117', '98', '1');

-- Template #50: S. Uric Acid (Category ID: 116)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S. Uric Acid', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Uric Acid</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Male: 3.5 - 7.2 mg/dL<br>Adult Female: 2.6 - 6.0 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Uricase / Enzymatic Colorimetric Method. Specimen: Serum.</div>\n</div>', '116', '98', '1');

-- Template #51: S. Creatinine (Category ID: 115)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S. Creatinine', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Creatinine</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Male: 0.70 - 1.30 mg/dL (62 - 115 umol/L)<br>Adult Female: 0.50 - 1.10 mg/dL (44 - 97 umol/L)<br>Children: 0.30 - 0.70 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">eGFR (CKD-EPI Formula)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mL/min/1.73m&sup2;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 90 : Normal kidney function<br>60 - 89 : Mild decrease<br>&lt; 60 : Reduced GFR (suspicious for CKD)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Modified Jaffe Kinetic / Enzymatic IDMS-traceable. Specimen: Serum.</div>\n</div>', '115', '98', '1');

-- Template #52: Blood Urea (Category ID: 114)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Blood Urea', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Blood Urea</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">15 - 45 mg/dL (2.5 - 7.5 mmol/L)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Blood Urea Nitrogen (BUN)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">7 - 20 mg/dL (BUN = Urea &divide; 2.14)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Urease-GLDH Kinetic Method. Specimen: Serum.</div>\n</div>', '114', '98', '1');

-- Template #53: Lipid Profile (Category ID: 113)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Lipid Profile', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Lipid Fraction</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">NCEP ATP III Clinical Guidelines</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Total Cholesterol</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Desirable: &lt; 200 mg/dL<br>Borderline High: 200 - 239 mg/dL<br>High: &ge; 240 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Triglycerides (TG)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Normal: &lt; 150 mg/dL<br>Borderline High: 150 - 199 mg/dL<br>High: 200 - 499 mg/dL<br>Very High: &ge; 500 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">HDL Cholesterol (\'Good\')</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Male: &gt; 40 mg/dL<br>Female: &gt; 50 mg/dL<br>High (Protective): &ge; 60 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">LDL Cholesterol (\'Bad\')</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Optimal: &lt; 100 mg/dL<br>Near Optimal: 100 - 129 mg/dL<br>Borderline High: 130 - 159 mg/dL<br>High: 160 - 189 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">VLDL Cholesterol</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">10 - 30 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Total Cholesterol / HDL Ratio</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">-</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Desirable: &lt; 4.5</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Serum collected after 10-12 hours overnight fasting. Method: Enzymatic Colorimetric.</div>\n</div>', '113', '98', '1');

-- Template #54: S. Cholesterol (Category ID: 112)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S. Cholesterol', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval (NCEP ATP III)</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Total Cholesterol</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Desirable: &lt; 200 mg/dL<br>Borderline High: 200 - 239 mg/dL<br>High: &ge; 240 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: CHOD-PAP Enzymatic Photometric Method. Specimen: Fasting Serum.</div>\n</div>', '112', '98', '1');

-- Template #55: S. Calcium (Category ID: 111)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S. Calcium', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Serum Total Calcium</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adults: 8.5 - 10.5 mg/dL (2.12 - 2.62 mmol/L)<br>Children: 8.8 - 10.8 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Arsenazo III / CPC Colorimetric. Corrected Calcium should be evaluated if serum albumin is abnormal.</div>\n</div>', '111', '98', '1');

-- Template #56: SGPT (Category ID: 110)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('SGPT', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">SGPT (Alanine Aminotransferase / ALT)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Males: &lt; 45 U/L<br>Adult Females: &lt; 34 U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: IFCC without Pyridoxal Phosphate. Specimen: Serum (Non-hemolyzed).</div>\n</div>', '110', '98', '1');

-- Template #57: SGOT (Category ID: 109)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('SGOT', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">SGOT (Aspartate Aminotransferase / AST)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adult Males: &lt; 40 U/L<br>Adult Females: &lt; 32 U/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: IFCC without Pyridoxal Phosphate. Specimen: Serum (Non-hemolyzed).</div>\n</div>', '109', '98', '1');

-- Template #58: HBS Ag (Screening) (Category ID: 108)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('HBS Ag (Screening)', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Method</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Value</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Hepatitis B Surface Antigen (HBsAg)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NON-REACTIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Immunochromatographic Rapid Assay (ICT)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Non-Reactive</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Serum. A non-reactive result does not rule out HBV infection during the early incubation/window period.</div>\n</div>', '108', '98', '1');

-- Template #59: S. Bilirubin (Category ID: 107)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('S. Bilirubin', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Bilirubin Fraction</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Bilirubin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">0.2 - 1.2 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Direct (Conjugated) Bilirubin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">0.0 - 0.3 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Indirect (Unconjugated) Bilirubin</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">0.2 - 0.8 mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: DPD / Diazo Colorimetric Method. Specimen: Serum protected from light.</div>\n</div>', '107', '98', '1');

-- Template #60: OGTT (Category ID: 106)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('OGTT', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Sample Timing</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Plasma Glucose</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Corresponding mg/dL</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">WHO Diagnostic Thresholds</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Urine Sugar</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">0 Hour (Fasting)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong> mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Normal: &lt; 6.1 mmol/L (&lt; 110 mg/dL)<br>Diabetes: &ge; 7.0 mmol/L (&ge; 126 mg/dL)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">1 Hour (Post 75g Glucose)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong> mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&lt; 10.0 mmol/L (&lt; 180 mg/dL)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">2 Hours (Post 75g Glucose)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong> mmol/L</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mg/dL</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Normal: &lt; 7.8 mmol/L (&lt; 140 mg/dL)<br>IGT: 7.8 - 11.0 mmol/L (140 - 199 mg/dL)<br>Diabetes: &ge; 11.1 mmol/L (&ge; 200 mg/dL)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Nil</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Conclusion / Interpretation</div>\n<div style=\"padding:8px; border:1px solid #d0d7de; background:#fff; min-height:40px;\">\nNormal Glucose Tolerance.\n</div>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Procedure: 75g anhydrous oral glucose dissolved in 250-300 ml water consumed within 5 minutes after 8-10 hrs fasting.</div>\n</div>', '106', '98', '1');

-- Template #61: BT, CT (Category ID: 104)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('BT, CT', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Investigation</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Method</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Bleeding Time (BT)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp; Min &nbsp; Sec</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Duke\'s Method</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">1 - 5 Minutes</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Clotting Time (CT)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp; Min &nbsp; Sec</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Capillary Glass Tube Method</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">4 - 10 Minutes</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Primary screening tests for platelet function and intrinsic coagulation pathway.</div>\n</div>', '104', '98', '1');

-- Template #62: C/E Count/Platelet Count (Category ID: 103)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('C/E Count/Platelet Count', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Test Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Unit</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Flag</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Circulating Eosinophils (AEC)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">/cu.mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">50 - 450 /cu.mm (0.05 - 0.45 x 10&sup9;/L)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Total Platelet Count</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>&nbsp;</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">/cu.mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">150,000 - 450,000 /cu.mm (150 - 450 x 10&sup9;/L)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp;</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Direct Counting (Fuchs-Rosenthal Chamber / Neubauer Chamber) & Automated Cell Counter. Specimen: EDTA Blood.</div>\n</div>', '103', '98', '1');

-- Template #63: ICT for Malaria (Category ID: 102)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('ICT for Malaria', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Malarial Antigen Target</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Result</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Target Species</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Value</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Plasmodium falciparum (HRP-2) Antigen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">P. falciparum</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Negative</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Plasmodium vivax (pLDH) Antigen</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\"><strong>NEGATIVE</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">P. vivax / Pan-species</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Negative</td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Method: Rapid Immunochromatographic Assay (RDT). Specimen: Whole Blood. Microscopic blood film examination is recommended for parasite confirmation and species verification.</div>\n</div>', '102', '98', '1');

-- Template #64: M.P (Category ID: 101)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('M.P', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Examination</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Observation / Microscopic Findings</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Thick Blood Film (Dehemoglobinized)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">No Malarial Parasite (Trophozoite, Schizont, or Gametocyte) seen after examining 200 oil immersion fields.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Thin Blood Film (Leishman / Giemsa)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">RBC morphology normal. No intracellular ring forms or Schuffner\'s/Maurer\'s dots seen.</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Final Result</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\"><strong>NEGATIVE FOR MALARIAL PARASITES (MP)</strong></td></tr>\n</tbody>\n</table>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Specimen: Capillary / EDTA Venous Blood. A single negative smear does not exclude malaria; repeat smear during fever spike recommended if fever persists.</div>\n</div>', '101', '98', '1');

-- Template #65: CBC (Category ID: 100)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('CBC', '<div class=\"cbc-report-body\" style=\"font-family: Arial, Helvetica, sans-serif; font-size: 13px; color: #000; line-height: 1.4;\">\n    <!-- Analyzer Method Note (Placed immediately below patient box) -->\n    <div style=\"text-align: center; font-style: italic; font-size: 12px; color: #222; margin-top: 4px; margin-bottom: 8px;\">\n        ( Relevent estimations were carried out by RAYTO RT-7600 Automated Haematology Analyzer &amp; checked manually )\n    </div>\n\n    <!-- Title Badge -->\n    <div style=\"text-align: center; margin-bottom: 12px;\">\n        <span style=\"display: inline-block; border: 1.5px solid #333; border-radius: 3px; padding: 3px 28px; font-weight: bold; font-size: 13.5px; text-transform: uppercase; letter-spacing: 1px; color: #000; background: #fff; box-shadow: 2px 2px 0px rgba(0,0,0,0.2);\">\n            HAEMATOLOGY REPORT\n        </span>\n    </div>\n\n    <!-- Results Table -->\n    <table style=\"width: 100%; border-collapse: collapse; font-family: Arial, Helvetica, sans-serif; font-size: 12.5px; color: #000;\">\n        <thead>\n            <tr style=\"border-top: 1.5px solid #222; border-bottom: 1.5px solid #222;\">\n                <th style=\"text-align: left; padding: 5px 4px; font-weight: bold; width: 34%;\">Parameter</th>\n                <th style=\"text-align: left; padding: 5px 4px; font-weight: bold; width: 13%;\">Results</th>\n                <th style=\"text-align: left; padding: 5px 4px; font-weight: bold; width: 13%;\">Unit</th>\n                <th style=\"text-align: left; padding: 5px 4px; font-weight: bold; width: 24%;\">Reference Values <!-- Reference Interval --></th>\n                <th style=\"text-align: center; padding: 5px 4px; font-weight: bold; width: 16%;\">Histogram</th>\n            </tr>\n        </thead>\n        <tbody>\n            <!-- 1. Haemoglobin & ESR -->\n            <tr>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">Haemoglobin(Hb)</td>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">15.4</td>\n                <td style=\"padding: 4px 4px;\">g/dl</td>\n                <td style=\"padding: 4px 4px;\">M:12.0-18.0, F:11.5-16.5 g/dl</td>\n                <td></td>\n            </tr>\n            <tr>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">ESR(Westergren)</td>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">08</td>\n                <td style=\"padding: 4px 4px;\">mm/1st hr</td>\n                <td style=\"padding: 4px 4px;\">M:0-10, F:0-20 mm/1st hr</td>\n                <td></td>\n            </tr>\n\n            <!-- Spacing -->\n            <tr><td colspan=\"5\" style=\"height: 6px;\"></td></tr>\n\n            <!-- 2. WBC Count -->\n            <tr>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">TOTAL WBC COUNT</td>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">10,850</td>\n                <td style=\"padding: 4px 4px;\">/cumm</td>\n                <td style=\"padding: 4px 4px;\">4,000 - 11,000 /cumm</td>\n                <td></td>\n            </tr>\n\n            <!-- 3. Differential Count + WBC Histogram Curve -->\n            <tr>\n                <td style=\"padding: 4px 4px; font-weight: bold; text-decoration: underline;\" colspan=\"4\">DIFFERENTIAL COUNT</td>\n                <td rowspan=\"6\" style=\"vertical-align: middle; text-align: center; padding: 2px;\">\n                    <img src=\"data:image/svg+xml;base64,\" alt=\"WBC CURVE\" width=\"120\" height=\"85\" style=\"display:block; margin:auto; border:none;\" />\n                </td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">Neutrophils</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">52</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">40 -70 %</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">Lymphocytes</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">41</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">20-50 %</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">Monocytes</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">04</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">02-10 %</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">Eosinophils</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">03</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">01-06 %</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">Basophil</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">00</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">00-01 %</td>\n            </tr>\n\n            <!-- Spacing -->\n            <tr><td colspan=\"5\" style=\"height: 6px;\"></td></tr>\n\n            <!-- 4. Eosinophil & Platelets + PLT Histogram Curve -->\n            <tr>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">TOTAL CIR. EOSIONOPHIL COUNT</td>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">326</td>\n                <td style=\"padding: 4px 4px;\">/cumm</td>\n                <td style=\"padding: 4px 4px;\">40 - 450 /cumm</td>\n                <td></td>\n            </tr>\n            <tr>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">TOTAL PLATELET COUNT(PC)</td>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">314,000</td>\n                <td style=\"padding: 4px 4px;\">/cumm</td>\n                <td style=\"padding: 4px 4px;\">1,50,000-4,50,000 /cumm</td>\n                <td rowspan=\"4\" style=\"vertical-align: middle; text-align: center; padding: 2px;\">\n                    <img src=\"data:image/svg+xml;base64,\" alt=\"PLT CURVE\" width=\"120\" height=\"85\" style=\"display:block; margin:auto; border:none;\" />\n                </td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">MPV</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">7.3</td>\n                <td style=\"padding: 2.5px 4px;\">m^3</td>\n                <td style=\"padding: 2.5px 4px;\">7.0 -11.0 m^3</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">PDW</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">13.7</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">10 - 18 %</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">PCT</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">0.23</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">0.2 - 0.5 %</td>\n            </tr>\n\n            <!-- Spacing -->\n            <tr><td colspan=\"5\" style=\"height: 6px;\"></td></tr>\n\n            <!-- 5. RBC Count & Indices + RBC Histogram Curve -->\n            <tr>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">RBC COUNT</td>\n                <td style=\"padding: 4px 4px; font-weight: bold;\">6.19</td>\n                <td style=\"padding: 4px 4px;\">m/ul</td>\n                <td style=\"padding: 4px 4px;\">M: 4.5-6.5, F: 3.8-5.8 m/ul</td>\n                <td rowspan=\"9\" style=\"vertical-align: middle; text-align: center; padding: 2px;\">\n                    <img src=\"data:image/svg+xml;base64,\" alt=\"RBC CURVE\" width=\"120\" height=\"85\" style=\"display:block; margin:auto; border:none;\" />\n                </td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">HCT/PCV</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">45.2</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">M: 40-54%, F: 37-47%</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">MCV</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">72.9</td>\n                <td style=\"padding: 2.5px 4px;\">fL</td>\n                <td style=\"padding: 2.5px 4px;\">76-94 fL</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">MCH</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">24.8</td>\n                <td style=\"padding: 2.5px 4px;\">pg</td>\n                <td style=\"padding: 2.5px 4px;\">27-32 pg</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">MCHC</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">34</td>\n                <td style=\"padding: 2.5px 4px;\">g/dL</td>\n                <td style=\"padding: 2.5px 4px;\">29-34 g/dl</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">RDW-SD</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">42.4</td>\n                <td style=\"padding: 2.5px 4px;\">fL</td>\n                <td style=\"padding: 2.5px 4px;\">37.0 - 54.0 fL</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">RDW-CV</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">15.2</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">11.5 - 14.5%</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 2.5px 4px 2.5px 18px;\">P LCR</td>\n                <td style=\"padding: 2.5px 4px; font-weight: bold;\">12.1</td>\n                <td style=\"padding: 2.5px 4px;\">%</td>\n                <td style=\"padding: 2.5px 4px;\">13.0 - 43.0 %</td>\n            </tr>\n        </tbody>\n    </table>\n</div>', '100', '98', '1');

-- Template #66: Echocardiography (2D & Color) (Category ID: 99993)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Echocardiography (2D & Color)', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">2D & M-Mode Measurements</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Value</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Value</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Reference Interval</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">LVDd</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">36 - 54 mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Ejection Fraction (EF)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center; font-weight:600;\" style=\"font-size:14px; color:#1a3a60;\"><strong>&nbsp; %</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">&ge; 55 %</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">LVDs</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">22 - 38 mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Fractional Shortening (FS)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; %</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">28 - 44 %</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">IVS (Diastole)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">6 - 11 mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Left Atrium (LA)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">20 - 40 mm</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">LVPW (Diastole)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">6 - 11 mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Aortic Root</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; mm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">20 - 37 mm</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Color Doppler & Valvular Assessment</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Mitral Valve:</strong> Normal leaflet motion. No mitral stenosis or significant regurgitation.<br>\n&bull; <strong>Aortic Valve:</strong> Trileaflet, opens well. No aortic stenosis or regurgitation.<br>\n&bull; <strong>Tricuspid Valve:</strong> Grossly normal. Trace tricuspid regurgitation (physiological). Estimated PASP normal.<br>\n&bull; <strong>Pulmonary Valve:</strong> Normal anatomy and forward flow velocity.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Structural Findings</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Left Ventricle:</strong> Normal LV chamber dimensions and wall thickness. Good global systolic contraction.<br>\n&bull; <strong>Regional Wall Motion:</strong> No regional wall motion abnormality (RWMA) at rest.<br>\n&bull; <strong>Right Ventricle & Atria:</strong> Normal size and function. TAPSE normal.<br>\n&bull; <strong>Pericardium:</strong> No pericardial effusion seen.<br>\n&bull; <strong>Intracardiac Clot / Shunt:</strong> No clot or mass seen. Interatrial septum appears intact.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression & Conclusion</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60; line-height:1.6;\">\n1. Normal cardiac chambers size with good global LV systolic function (EF: &nbsp;%).<br>\n2. No resting regional wall motion abnormality (RWMA).<br>\n3. Normal valvular morphology and Doppler hemodynamics.<br>\n4. No pericardial effusion.\n</div>\n</div>', '99993', '98', '1');

-- Template #67: Nebulization (Category ID: 158)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Nebulization', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Procedure Record Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Clinical Entry</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Indication</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Bronchospasm / Acute Wheeze / Acute Asthma Exacerbation</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Medication & Dosage Administered</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Nebulization with Salbutamol (2.5 mg) &amp; Ipratropium Bromide (0.5 mg) respule with 2.5 ml Normal Saline</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Delivery Method</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Jet Nebulizer with Face Mask via Medical Oxygen / Compressed Air (6 L/min)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Pre-Procedure Vitals</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Pulse: &nbsp; bpm; SpO2: &nbsp; % (on room air); RR: &nbsp; /min; Chest: Rhonchi present</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Post-Procedure Evaluation</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Pulse: &nbsp; bpm; SpO2: &nbsp; %; RR: &nbsp; /min; Chest: Significant reduction in wheeze; good air entry</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Adverse Reaction / Complication</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">None reported. Procedure tolerated well.</td></tr>\n</tbody>\n</table>\n</div>', '158', '98', '1');

-- Template #68: ECG (Category ID: 157)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('ECG', '<div style=\"font-family: Arial, sans-serif;\">\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">ECG Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Observed Value</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">ECG Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:center;\">Observed Value</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Heart Rate</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">&nbsp; bpm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">P-R Interval</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">0.16 sec (0.12 - 0.20)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Rhythm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Normal Sinus Rhythm</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">QRS Duration</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">0.08 sec (&lt; 0.12)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Mean QRS Axis</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">Normal Axis</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">QT / QTc Interval</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:center;\">0.38 / 0.42 sec (&lt; 0.44)</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Detailed Waveform Analysis</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>P Wave:</strong> Normal amplitude and morphology in leads II and V1.<br>\n&bull; <strong>QRS Complex:</strong> Normal R wave progression in chest leads V1 to V6. No pathological Q waves.<br>\n&bull; <strong>ST Segment:</strong> Isoelectric in all standard and precordial leads. No ST elevation or depression.<br>\n&bull; <strong>T Wave:</strong> Normal upright morphology in leads I, II, aVL, V2-V6. No pathological inversion.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Electrocardiographic Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL 12-LEAD RESTING ELECTROCARDIOGRAM (ECG).<br>\n<small style=\"font-weight:normal; color:#666;\">Normal sinus rhythm with normal axis, intervals, and repolarization pattern.</small>\n</div>\n<div style=\"margin-top:12px; padding:8px 12px; background:#fafbfc; border-left:3px solid #007bff; font-size:12px; color:#555;\"><strong>Note:</strong> Recorded at 25 mm/sec speed and 10 mm/mV voltage calibration.</div>\n</div>', '157', '98', '1');

-- Template #69: USG- KUB (Category ID: 156)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('USG- KUB', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">ULTRASONOGRAPHY OF KIDNEYS, URETERS & BLADDER (KUB)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Right Kidney:</strong> Normal in size (&nbsp; x &nbsp; mm), shape, and position. Normal cortical thickness and parenchymal echogenicity. Corticomedullary differentiation is well preserved. No calculus, solid focal lesion, or hydronephrosis seen.<br>\n&bull; <strong>Left Kidney:</strong> Normal in size (&nbsp; x &nbsp; mm), shape, and position. Normal cortical thickness and parenchymal echogenicity. Good corticomedullary demarcation. No calculus, solid mass, or hydronephrosis seen.<br>\n&bull; <strong>Ureters:</strong> Both ureters are not dilated.<br>\n&bull; <strong>Urinary Bladder:</strong> Well distended with clear anechoic lumen. Walls are smooth with normal thickness. No calculus, polyp, or mass lesion seen.<br>\n&bull; <strong>Prostate (Male):</strong> Normal in size and volume (~ &nbsp; gm). Echo texture is homogeneous. Capsule is intact. Post-void residual (PVR) volume is insignificant (&lt; 20 mL).\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL ULTRASONOGRAPHIC STUDY OF KIDNEYS, URETERS AND URINARY BLADDER (KUB).<br>\n<small style=\"font-weight:normal; color:#666;\">No calculus, hydronephrosis, or space-occupying lesion seen.</small>\n</div>\n</div>', '156', '98', '1');

-- Template #70: USG-HBS (Category ID: 155)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('USG-HBS', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">ULTRASONOGRAPHY OF HEPATOBILIARY SYSTEM (HBS)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Liver:</strong> Normal in size (Span: &nbsp; cm). Capsule is smooth and regular. Parenchymal echogenicity is normal and homogeneous. No focal mass, cyst, or space-occupying lesion seen. Intrahepatic biliary channels (IHBR) are not dilated.<br>\n&bull; <strong>Portal Vein:</strong> Normal in caliber (&le; 11 mm) with normal hepatopetal flow.<br>\n&bull; <strong>Gall Bladder:</strong> Well distended. Wall is thin, smooth, and measures &lt; 3 mm. Lumen is clear and anechoic. No calculus, sludge, or polyp seen.<br>\n&bull; <strong>Common Bile Duct (CBD):</strong> Normal in caliber (measures &nbsp; mm; &le; 6 mm). No intraductal calculus or dilatation.<br>\n&bull; <strong>Spleen:</strong> Normal in size (Length: &nbsp; cm; &le; 12 cm) and homogeneous in echogenicity. Splenic vein is normal.<br>\n&bull; <strong>Pancreas:</strong> Head, body, and visualized tail appear normal in size and echotexture. Main pancreatic duct is not dilated.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL ULTRASONOGRAM OF HEPATOBILIARY SYSTEM (HBS).<br>\n<small style=\"font-weight:normal; color:#666;\">No hepatomegaly, focal liver lesion, cholelithiasis, or splenomegaly seen.</small>\n</div>\n</div>', '155', '98', '1');

-- Template #71: USG- Pregnancy Profile (Category ID: 154)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('USG- Pregnancy Profile', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">OBSTETRIC ULTRASONOGRAPHY REPORT (PREGNANCY PROFILE)</div>\n<table style=\"width:100%; border-collapse:collapse; margin-bottom:15px; font-family:\'Segoe UI\', Roboto, Arial, sans-serif; font-size:13px; color:#333;\">\n<thead><tr><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Fetal Parameter</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Measurement / Finding</th><th style=\"background:#f1f4f9; color:#1a3a60; font-weight:700; border:1px solid #d0d7de; padding:8px 10px; text-align:left;\">Biometric Age</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Number of Fetuses</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Single intrauterine pregnancy</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">-</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Presentation &amp; Lie</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Cephalic / Longitudinal</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">-</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Fetal Cardiac Activity</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Present &amp; Regular</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"Fetal Heart Rate: &nbsp; bpm (120-160)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Fetal Movement</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Present &amp; Active</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">-</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Biparietal Diameter (BPD)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"<strong>&nbsp; mm</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"Corresponding to &nbsp; Wks &plusmn; &nbsp; Days</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Head Circumference (HC)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"<strong>&nbsp; mm</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"Corresponding to &nbsp; Wks &plusmn; &nbsp; Days</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Abdominal Circumference (AC)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"<strong>&nbsp; mm</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"Corresponding to &nbsp; Wks &plusmn; &nbsp; Days</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Femur Length (FL)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"<strong>&nbsp; mm</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"Corresponding to &nbsp; Wks &plusmn; &nbsp; Days</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Estimated Fetal Weight (EFW)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"<strong>&nbsp; grams (&plusmn; 10%)</strong></td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Hadlock Formula</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Placenta</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Location: Anterior / Posterior; Maturity: Grade I/II; Distance from internal os is adequate (&gt; 2.5 cm)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\"No previa / retroplacental clot</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Amniotic Fluid Index (AFI)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">AFI: &nbsp; cm (Single deepest pocket: &nbsp; cm)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Adequate (Normal: 8 - 18 cm)</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Gross Anomaly Survey</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Cranium, spine, stomach bubble, 4-chamber heart view, kidneys, and bladder are visualized and appear grossly normal</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">No gross anomaly detected</td></tr>\n<tr><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left; font-weight:600;\">Cervical Length</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Internal os closed. Cervix measures &nbsp; mm (&gt; 30 mm)</td><td style=\"border:1px solid #e1e4e8; padding:7px 10px; text-align:left;\">Competent internal os</td></tr>\n</tbody>\n</table>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression & Obstetric Summary</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60; line-height:1.7;\">\n&bull; Single live intrauterine pregnancy of &nbsp; weeks &plusmn; &nbsp; days by composite ultrasound biometry.<br>\n&bull; Presentation: Cephalic with active fetal cardiac activity.<br>\n&bull; Placenta: Anterior/Posterior, Grade &nbsp;, no previa.<br>\n&bull; Amniotic fluid volume is adequate.<br>\n&bull; Expected Date of Delivery (EDD by USG): &nbsp;<br>\n<small style=\"font-weight:normal; color:#666;\">Clinical correlation with LMP and regular antenatal follow-up recommended.</small>\n</div>\n</div>', '154', '98', '1');

-- Template #72: USG- Lower Abdomen (Category ID: 153)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('USG- Lower Abdomen', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">ULTRASONOGRAPHY OF LOWER ABDOMEN & PELVIS</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Urinary Bladder:</strong> Well distended. Wall is thin, regular, and normal in thickness. Lumen is free of calculus, mass, or intraluminal lesion.<br>\n&bull; <strong>Prostate (Male):</strong> Normal size and shape. Measures approximately &nbsp; x &nbsp; x &nbsp; mm with estimated volume of &nbsp; grams (&le; 25 gm). Parenchyma is homogeneous. Capsule is smooth. Insignificant post-void residue.<br>\n&bull; <strong>Uterus &amp; Adnexa (Female):</strong> Uterus is normal in size, anteverted, and regular in outline. Myometrium shows uniform echogenicity without fibroid or mass. Endometrial stripe is central and measures &nbsp; mm. Both ovaries are normal in size and follicular pattern. No adnexal mass or cyst seen.<br>\n&bull; <strong>Pouch of Douglas (POD):</strong> No free fluid or collection seen in pelvis.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL ULTRASONOGRAPHIC STUDY OF LOWER ABDOMEN AND PELVIS.<br>\n<small style=\"font-weight:normal; color:#666;\">No pelvic mass, cyst, urinary bladder pathology, or free fluid detected.</small>\n</div>\n</div>', '153', '98', '1');

-- Template #73: USG- Upper Abdomen (Category ID: 152)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('USG- Upper Abdomen', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">ULTRASONOGRAPHY OF UPPER ABDOMEN</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Liver:</strong> Normal in size (Span: &nbsp; cm). Outline is regular. Echo texture is homogeneous. No focal mass, cyst, or SOL seen. Intrahepatic biliary radicals are not dilated.<br>\n&bull; <strong>Gall Bladder:</strong> Well filled. Wall is thin and smooth (&lt; 3 mm). No gallstones, sludge, or polyp seen. CBD is normal in caliber.<br>\n&bull; <strong>Spleen:</strong> Normal in size and echogenicity. Splenic vein is normal.<br>\n&bull; <strong>Pancreas:</strong> Normal in size and echotexture. No focal lesion or ductal dilatation.<br>\n&bull; <strong>Kidneys (Upper Poles &amp; Vis.):</strong> Both kidneys are visualized and appear normal in size, position, and cortical thickness. No hydronephrosis or calculi seen.<br>\n&bull; <strong>Peritoneum:</strong> No ascites or lymphadenopathy in upper abdomen.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL ULTRASONOGRAPHIC STUDY OF UPPER ABDOMEN.<br>\n<small style=\"font-weight:normal; color:#666;\">No hepatosplenomegaly, cholelithiasis, or solid organ focal lesion detected.</small>\n</div>\n</div>', '152', '98', '1');

-- Template #74: USG- Whole Abdomen (Category ID: 151)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('USG- Whole Abdomen', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">COMPREHENSIVE ULTRASONOGRAPHY OF WHOLE ABDOMEN & PELVIS</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Liver:</strong> Normal in size (Span: &nbsp; cm). Smooth surface and uniform parenchymal echogenicity. No focal lesion, cyst, or SOL seen. Intrahepatic biliary channels and portal vein are normal.<br>\n&bull; <strong>Gall Bladder:</strong> Well distended. Wall is thin and smooth (&lt; 3 mm). Lumen is clear without calculus, sludge, or mass.<br>\n&bull; <strong>Common Bile Duct (CBD):</strong> Normal in caliber (&nbsp; mm; &le; 6 mm).<br>\n&bull; <strong>Spleen:</strong> Normal in size (Length: &nbsp; cm) and homogeneous in echotexture. No focal lesion.<br>\n&bull; <strong>Pancreas:</strong> Visualized head and body appear normal in size and echogenicity. Duct is not dilated.<br>\n&bull; <strong>Right Kidney:</strong> Normal in size (&nbsp; x &nbsp; mm), shape, and cortical thickness. Good corticomedullary differentiation. No calculus, hydronephrosis, or space-occupying lesion seen.<br>\n&bull; <strong>Left Kidney:</strong> Normal in size (&nbsp; x &nbsp; mm), shape, and cortical thickness. Good corticomedullary differentiation. No calculus, hydronephrosis, or space-occupying lesion seen.<br>\n&bull; <strong>Urinary Bladder:</strong> Well distended with clear lumen. Smooth, normal wall thickness. No calculus or mass seen.<br>\n&bull; <strong>Prostate / Uterus:</strong> Normal in size, contour, and internal echo pattern for age.<br>\n&bull; <strong>Peritoneum &amp; Retroperitoneum:</strong> No ascites / free fluid in abdominal cavity or pelvis. No para-aortic lymphadenopathy.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression & Conclusion</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL ULTRASONOGRAPHIC STUDY OF WHOLE ABDOMEN.<br>\n<small style=\"font-weight:normal; color:#666;\">No organomegaly, focal parenchymal mass, cholelithiasis, nephrolithiasis, or ascites seen.</small>\n</div>\n</div>', '151', '98', '1');

-- Template #75: Leg B/V (Category ID: 150)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Leg B/V', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY OF LEG (TIBIA & FIBULA) BOTH VIEWS (A/P & LATERAL)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Bony architecture and cortical continuity of Tibia and Fibula shafts are well maintained.<br>\n&bull; No fracture line, cortical disruption, or dislocation seen.<br>\n&bull; Knee joint and Ankle joint spaces included are within normal limits.<br>\n&bull; No evidence of osteolytic or osteoblastic bone lesion.<br>\n&bull; Surrounding soft tissue shadows appear normal without swelling or foreign body.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNO RADIOLOGICAL EVIDENCE OF BONE FRACTURE OR DISLOCATION IN THE EXAMINED LEG (TIBIA &amp; FIBULA).\n</div>\n</div>', '150', '98', '1');

-- Template #76: Hand B/V (Category ID: 149)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Hand B/V', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY OF HAND BOTH VIEWS (A/P & OBLIQUE)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; All visualized metacarpals and phalanges show intact cortical margins.<br>\n&bull; Visualized carpal bones are normal in alignment and architecture.<br>\n&bull; No fracture, dislocation, or subluxation seen.<br>\n&bull; Interphalangeal and metacarpophalangeal joint spaces are preserved.<br>\n&bull; Soft tissue shadows are within normal limits.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF HAND (A/P &amp; OBLIQUE VIEWS). NO EVIDENCE OF RECENT FRACTURE OR JOINT DISLOCATION.\n</div>\n</div>', '149', '98', '1');

-- Template #77: Pelvis A/P (Category ID: 148)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Pelvis A/P', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY PELVIS WITH BOTH HIP JOINTS (A/P VIEW)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Pelvic ring and obturator rings are intact with smooth cortical margins.<br>\n&bull; Both femoral heads are spherical and congruent within normal acetabular fossae.<br>\n&bull; Femoral necks, greater and lesser trochanters appear intact without fracture.<br>\n&bull; Both Sacroiliac (SI) joints and Pubic Symphysis are normal in alignment and width.<br>\n&bull; No evidence of osteolytic/sclerotic lesion or pelvic bone fracture.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF PELVIS (A/P VIEW). NO EVIDENCE OF FRACTURE, DISLOCATION, OR AVASCULAR NECROSIS.\n</div>\n</div>', '148', '98', '1');

-- Template #78: Dorsal Spine B/V (Category ID: 147)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Dorsal Spine B/V', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY DORSAL (THORACIC) SPINE BOTH VIEWS (A/P & LATERAL)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Normal thoracic kyphosis and vertebral column alignment.<br>\n&bull; Vertebral body heights are maintained without compression fracture or collapse.<br>\n&bull; Intervertebral disc spaces are preserved throughout the thoracic spine.<br>\n&bull; Pedicles, spinous processes, and costovertebral articulations are intact.<br>\n&bull; No paravertebral soft tissue shadow or calcification seen.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF DORSAL SPINE (A/P &amp; LATERAL VIEWS). NO EVIDENCE OF FRACTURE OR SIGNIFICANT SPONDYLOTIC CHANGE.\n</div>\n</div>', '147', '98', '1');

-- Template #79: L/S Spine B/V (Category ID: 146)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('L/S Spine B/V', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY LUMBO-SACRAL (L/S) SPINE BOTH VIEWS (A/P & LATERAL)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Normal lumbar lordotic curvature is preserved.<br>\n&bull; Vertebral bodies (L1 to L5) show normal height, alignment, and bone density.<br>\n&bull; Intervertebral disc spaces (particularly L4-L5 and L5-S1) appear adequate.<br>\n&bull; No evidence of spondylolisthesis, pars interarticularis defect, or compression fracture.<br>\n&bull; Pedicles and transverse processes are intact bilaterally.<br>\n&bull; Sacroiliac joints appear normal. No significant osteophytosis.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF LUMBO-SACRAL SPINE (A/P &amp; LATERAL VIEWS).<br>\n<small style=\"font-weight:normal; color:#666;\">No fracture, vertebral collapse, disc space narrowing, or listhesis seen.</small>\n</div>\n</div>', '146', '98', '1');

-- Template #80: Abdomen E/P (Category ID: 145)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Abdomen E/P', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY ABDOMEN ERECT & PLAIN (A/P VIEW)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; <strong>Subdiaphragmatic Spaces:</strong> Both domes of diaphragm are well visualized. No free air / gas under right or left dome of diaphragm (No pneumoperitoneum).<br>\n&bull; <strong>Bowel Gas Pattern:</strong> Normal stomach and colonic gas shadows. No multiple air-fluid levels or dilated small bowel loops (No bowel obstruction).<br>\n&bull; <strong>Psoas &amp; Renal Shadows:</strong> Outlines of both psoas muscles are clear and symmetric.<br>\n&bull; <strong>Radio-opaque Shadows:</strong> No abnormal radio-opaque shadow, calculus, or foreign body seen in the abdomen or pelvis.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL ERECT RADIOGRAPH OF ABDOMEN.<br>\n<small style=\"font-weight:normal; color:#666;\">No evidence of pneumoperitoneum (no bowel perforation) or bowel obstruction.</small>\n</div>\n</div>', '145', '98', '1');

-- Template #81: KUB (Category ID: 144)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('KUB', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY KIDNEYS, URETERS & BLADDER (KUB)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Outlines of both kidneys and psoas margins are visible in normal anatomical positions.<br>\n&bull; No radio-opaque calculus shadow seen along the renal silhouettes, line of ureters, or bladder region.<br>\n&bull; Normal abdominal bowel gas pattern.<br>\n&bull; Visualized lower ribs, lumbar vertebrae, and pelvic bones appear normal without fracture or destructive bone lesion.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNO RADIO-OPAQUE CALCULUS DETECTED ALONG THE URINARY TRACT (KUB REGION).\n</div>\n</div>', '144', '98', '1');

-- Template #82: Cervical Spine B/V (Category ID: 143)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Cervical Spine B/V', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY CERVICAL SPINE BOTH VIEWS (A/P & LATERAL)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Normal cervical lordosis is preserved.<br>\n&bull; Alignment of vertebral bodies (C1 to C7) is anatomical without subluxation.<br>\n&bull; Heights of all cervical vertebral bodies are maintained.<br>\n&bull; Intervertebral disc spaces are well preserved without narrowing.<br>\n&bull; Atlanto-dens interval (ADI) is normal (&lt; 3 mm). Spinous processes and pedicles are intact.<br>\n&bull; Prevertebral soft tissue shadow is within normal limits.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF CERVICAL SPINE (A/P &amp; LATERAL VIEWS).<br>\n<small style=\"font-weight:normal; color:#666;\">No evidence of fracture, dislocation, or cervical spondylosis.</small>\n</div>\n</div>', '143', '98', '1');

-- Template #83: Neck B/V (Category ID: 142)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Neck B/V', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY SOFT TISSUE NECK BOTH VIEWS (A/P & LATERAL)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Retropharyngeal and prevertebral soft tissue spaces are within normal limits for age.<br>\n&bull; Tracheal air column is central and patent without narrowing or deviation.<br>\n&bull; Epiglottis and aryepiglottic folds appear normal. No \'thumb sign\'.<br>\n&bull; Hyoid bone and laryngeal cartilages are normal.<br>\n&bull; No radio-opaque foreign body or soft tissue calcification seen.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF SOFT TISSUE NECK. NO EVIDENCE OF RETROPHARYNGEAL ABSCESS, AIRWAY OBSTRUCTION, OR RADIO-OPAQUE FOREIGN BODY.\n</div>\n</div>', '142', '98', '1');

-- Template #84: PNS O/M View (Category ID: 141)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('PNS O/M View', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY PARANASAL SINUSES OCCIPITO-MENTAL (WATER\'S) VIEW</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Both Maxillary Antra (Sinuses) are well aerated with clear, normal lucency.<br>\n&bull; No mucosal thickening, clouding, haziness, or fluid level seen in either maxillary sinus.<br>\n&bull; Frontal and Ethmoidal sinuses show normal pneumatization.<br>\n&bull; Nasal septum is central in position without significant deviation.<br>\n&bull; Orbital margins and facial bones appear intact.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF PARANASAL SINUSES (WATER\'S VIEW).<br>\n<small style=\"font-weight:normal; color:#666;\">No radiological evidence of acute or chronic sinusitis.</small>\n</div>\n</div>', '141', '98', '1');

-- Template #85: Skull B/V (Category ID: 140)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Skull B/V', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY SKULL BOTH VIEWS (A/P & LATERAL)</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Cranial vault bones (Frontal, Parietal, Occipital, and Temporal) show intact inner and outer tables.<br>\n&bull; Cranial sutures are normal in appearance and width.<br>\n&bull; No linear or depressed fracture line seen.<br>\n&bull; Vascular markings and digital impressions are within normal physiological limits.<br>\n&bull; Sella turcica is normal in size, shape, and cortical contour.<br>\n&bull; No focal osteolytic or blastic lesion. Soft tissue shadow of scalp is normal.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL RADIOGRAPH OF SKULL (A/P &amp; LATERAL VIEWS). NO EVIDENCE OF VAULT FRACTURE OR BONY LESION.\n</div>\n</div>', '140', '98', '1');

-- Template #86: Chest Lateral View (Category ID: 139)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Chest Lateral View', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY CHEST LATERAL VIEW</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Retrosternal and retrocardiac spaces are clear with normal lucency.<br>\n&bull; Posterior costophrenic angle is sharp and clear without effusion.<br>\n&bull; Thoracic vertebral bodies show normal height and density without collapse.<br>\n&bull; Trachea and major airways are patent.<br>\n&bull; Cardiac silhouette and hilar structures appear within normal limits.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL CHEST RADIOGRAPH (LATERAL VIEW). NO HILAR MASS, RETROCARDIAC CONSOLIDATION, OR EFFUSION.\n</div>\n</div>', '139', '98', '1');

-- Template #87: Chest A/P (Category ID: 138)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Chest A/P', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY CHEST ANTERO-POSTERIOR (A/P) VIEW</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Bilateral lung fields are well aerated.<br>\n&bull; No focal pulmonary consolidation, mass, cavitary lesion, or active infiltration seen.<br>\n&bull; Bronchovascular markings are normal in distribution.<br>\n&bull; Both costophrenic and cardiophrenic angles are clear.<br>\n&bull; Cardiac shadow is within normal limits (allowing for magnification of A/P projection).<br>\n&bull; Bony thorax and visualized ribs show no fracture.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL CHEST RADIOGRAPH (A/P VIEW). NO ACTIVE PULMONARY LESION OR PLEURAL EFFUSION SEEN.\n</div>\n</div>', '138', '98', '1');

-- Template #88: Chest P/A (Category ID: 137)
INSERT INTO `template` (`name`, `template`, `category_id`, `hospital_id`, `user`)
VALUES ('Chest P/A', '<div style=\"font-family: Arial, sans-serif;\">\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">PLAIN X-RAY CHEST POSTERO-ANTERIOR (P/A) VIEW</div>\n<div style=\"font-size:13px; line-height:1.7; padding:8px 10px; border:1px solid #e1e4e8; background:#fff;\">\n&bull; Both lung fields are clear with normal bilateral bronchovascular markings.<br>\n&bull; No parenchymal consolidation, infiltrate, nodule, mass, or cavity seen.<br>\n&bull; Both costophrenic and cardiophrenic angles are sharp and clear.<br>\n&bull; Cardiac silhouette is normal in size and contour. Cardiothoracic ratio (CTR) is &lt; 50%.<br>\n&bull; Aorta and superior mediastinum are within normal limits.<br>\n&bull; Trachea is central in position.<br>\n&bull; Both domes of diaphragm are smooth and normal in level and curvature.<br>\n&bull; Bony thoracic cage and surrounding soft tissues are unremarkable.\n</div>\n\n<div style=\"margin-top:14px; margin-bottom:6px; font-weight:700; color:#1a3a60; text-transform:uppercase; font-size:13px; border-bottom:1px solid #1a3a60; padding-bottom:3px;\">Impression</div>\n<div style=\"padding:10px; border:1px solid #d0d7de; background:#f9fbfe; font-size:14px; font-weight:600; color:#1a3a60;\">\nNORMAL CHEST RADIOGRAPH (P/A VIEW).<br>\n<small style=\"font-weight:normal; color:#666;\">No radiographic evidence of active pulmonary tuberculosis, consolidation, cardiomegaly, or pleural effusion.</small>\n</div>\n</div>', '137', '98', '1');

